mapper.select:
SELECT o.id AS id, o.product_id AS productId, p.name AS productName, p. json_attributes_name AS jsonAttributesName, p. type_products_name AS typeProductsName, o.order_status AS status, o. total_price AS totalAmount, o.total_payment AS totalPayment, p.json_attributes AS jsonAttributes, p.type_products AS typeProducts FROM orders o INNER JOIN products p ON o.product_id = p.id WHERE o.is_deleted = 'false'
AND o.status = #{status}
AND LOWER(o.id) LIKE CONCAT('%', LOWER(#{keyword}), '%')
ORDER BY o.created_at DESC, o.id DESC LIMIT #{pageSize} OFFSET #{offset}

